WITH enriched AS (SELECT id, session_id, event_type, page, event_time, duration_sec, NTILE(10) OVER (PARTITION BY event_type, page ORDER BY duration_sec, id) AS duration_sec_bucket, AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY duration_sec, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS duration_sec_avg_6, SUM(duration_sec) OVER (PARTITION BY session_id, page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec, AVG(duration_sec) OVER (PARTITION BY session_id) AS session_id_avg_duration_sec, MIN(duration_sec) OVER w_grp AS event_type_min_duration_sec FROM web_events WINDOW w_grp AS (PARTITION BY event_type, page)) SELECT id, session_id, event_type, page, duration_sec_bucket, duration_sec_avg_6, cumulative_duration_sec FROM enriched ORDER BY id DESC NULLS FIRST;
